using Full.NET.Data.Abstractions;

namespace Full.NET.Modules.Ai.Persistence;

/// <summary>FAQ 数据库来源与文件导入分别证明；普通文档条件保持原样，不通过伪造导入接线。</summary>
internal static class AiKnowledgeFaqIndexSql
{
    // version、document、knowledge 为统一索引语句的固定别名；不接受运行时表名或策略开关。
    internal const string Origin = "version.FileId IS NULL AND version.FaqRevisionId IS NOT NULL AND EXISTS (SELECT 1 FROM fn_ai_knowledge_faq_source AS faqOrigin INNER JOIN fn_ai_knowledge_faq AS managedFaq ON managedFaq.Id=faqOrigin.FaqId INNER JOIN fn_ai_knowledge_faq_revision AS faqRevision ON faqRevision.Id=faqOrigin.RevisionId AND faqRevision.FaqId=managedFaq.Id WHERE faqOrigin.Id=version.Id AND managedFaq.ReservedDocumentId=document.Id AND managedFaq.KnowledgeBaseId=knowledge.Id AND faqRevision.Id=version.FaqRevisionId AND faqOrigin.RevisionHash=faqRevision.ContentHash AND faqOrigin.SourceHash=managedFaq.SourceHash AND faqOrigin.BodyHash=version.ContentHash AND faqOrigin.SizeBytes=version.SizeBytes AND version.ContentType='text/plain' AND version.ParsingPolicyKey='faq-revision-text-v1')";
    internal const string CurrentOrigin = Origin + " AND EXISTS (SELECT 1 FROM fn_ai_knowledge_faq AS currentFaq WHERE currentFaq.ReservedDocumentId=document.Id AND currentFaq.HeadRevisionId=version.FaqRevisionId AND EXISTS (SELECT 1 FROM fn_ai_knowledge_faq_source AS approvedInput WHERE approvedInput.Id=version.Id AND approvedInput.KnowledgeBaseVersion=knowledge.Version AND approvedInput.ModelConfigId=knowledge.EmbeddingModelConfigId AND approvedInput.ModelConfigVersion=knowledge.EmbeddingModelVersion))";
    internal const string Classification = "CASE WHEN version.FaqRevisionId IS NULL THEN knowledge.DataClassification ELSE (SELECT faqPolicy.DataClassification FROM fn_ai_knowledge_faq_source AS faqPolicy WHERE faqPolicy.Id=version.Id AND faqPolicy.RevisionId=version.FaqRevisionId) END";
    internal const string SnapshotClassification = "CASE WHEN version.FaqRevisionId IS NULL THEN knowledge_snapshot.DataClassification ELSE (SELECT faqPolicy.DataClassification FROM fn_ai_knowledge_faq_source AS faqPolicy WHERE faqPolicy.Id=version.Id AND faqPolicy.RevisionId=version.FaqRevisionId) END";
    internal const string NullSafeFile = "((source.FileId=@FileId) OR (source.FileId IS NULL AND @FileId IS NULL AND source.FaqRevisionId IS NOT NULL))";

    private const string Columns = "input.Id,input.FaqId,input.RevisionId,input.RevisionHash,input.SourceHash,input.DataClassification,input.KnowledgeBaseVersion,input.ModelConfigId,input.ModelConfigVersion,input.ModelFingerprint,input.BodyText,input.BodyHash,input.SizeBytes,input.RequestKey,input.RequestHash,input.ActorUserId,input.CreatedAtUtc";
    private const string Root = " FROM fn_ai_knowledge_faq_source AS input INNER JOIN fn_ai_knowledge_faq AS f ON f.Id=input.FaqId INNER JOIN fn_ai_knowledge_base AS k ON k.Id=f.KnowledgeBaseId WHERE f.KnowledgeBaseId=@KnowledgeBaseId AND f.ReservedDocumentId=@DocumentId AND k.OwnerUserId=@OwnerUserId AND k.IsEnabled=1 AND ";
    private const string Host = "k.TenantId IS NULL AND f.TenantId IS NULL";
    private const string Tenant = "k.TenantId=@TenantId AND f.TenantId=@TenantId";
    internal static readonly SqlStatement FindHost = new("ai.knowledge_faq_source.find_host", "SELECT " + Columns + Root + Host + " AND input.Id=@VersionId", SqlDataScope.HostOnly);
    internal static readonly SqlStatement FindTenant = new("ai.knowledge_faq_source.find_tenant", "SELECT " + Columns + Root + Tenant + " AND input.Id=@VersionId", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement RevisionHost = new("ai.knowledge_faq_source.revision_host", "SELECT " + Columns + Root + Host + " AND input.RevisionId=@RevisionId", SqlDataScope.HostOnly);
    internal static readonly SqlStatement RevisionTenant = new("ai.knowledge_faq_source.revision_tenant", "SELECT " + Columns + Root + Tenant + " AND input.RevisionId=@RevisionId", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement KeyHost = new("ai.knowledge_faq_source.key_host", "SELECT " + Columns + Root + Host + " AND input.FaqId=@FaqId AND input.RequestKey=@RequestKey", SqlDataScope.HostOnly);
    internal static readonly SqlStatement KeyTenant = new("ai.knowledge_faq_source.key_tenant", "SELECT " + Columns + Root + Tenant + " AND input.FaqId=@FaqId AND input.RequestKey=@RequestKey", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);

    private const string SourceInsert = "INSERT INTO fn_ai_knowledge_faq_source (Id,FaqId,RevisionId,RevisionHash,SourceHash,DataClassification,KnowledgeBaseVersion,ModelConfigId,ModelConfigVersion,ModelFingerprint,BodyText,BodyHash,SizeBytes,RequestKey,RequestHash,ActorUserId,CreatedAtUtc) SELECT @VersionId,f.Id,@RevisionId,@RevisionHash,f.SourceHash,@DataClassification,@KnowledgeBaseVersion,@ModelConfigId,@ModelConfigVersion,@ModelFingerprint,@BodyText,@BodyHash,@SizeBytes,@RequestKey,@RequestHash,@OwnerUserId,@Now FROM fn_ai_knowledge_faq AS f INNER JOIN fn_ai_knowledge_base AS k ON k.Id=f.KnowledgeBaseId WHERE f.Id=@FaqId AND f.KnowledgeBaseId=@KnowledgeBaseId AND f.ReservedDocumentId=@DocumentId AND f.HeadRevisionId=@RevisionId AND f.HeadVersion=@ExpectedHeadVersion AND k.OwnerUserId=@OwnerUserId AND k.Version=@KnowledgeBaseVersion AND k.IsEnabled=1 AND ";
    internal static readonly SqlStatement InsertHost = new("ai.knowledge_faq_source.insert_host", SourceInsert + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement InsertTenant = new("ai.knowledge_faq_source.insert_tenant", SourceInsert + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    // 文档身份先由 FAQ 根保留；物化只允许该根的当前修订，不走普通文档创建入口。
    private const string DocumentInsert = "INSERT INTO fn_ai_knowledge_document (Id,KnowledgeBaseId,Title,Description,IsDeleted,CreatedAtUtc,Version) SELECT f.ReservedDocumentId,k.Id,@Title,NULL,0,@Now,@ExpectedHeadVersion FROM fn_ai_knowledge_faq AS f INNER JOIN fn_ai_knowledge_base AS k ON k.Id=f.KnowledgeBaseId WHERE f.Id=@FaqId AND f.ReservedDocumentId=@DocumentId AND f.KnowledgeBaseId=@KnowledgeBaseId AND f.HeadRevisionId=@RevisionId AND f.HeadVersion=@ExpectedHeadVersion AND k.OwnerUserId=@OwnerUserId AND k.IsEnabled=1 AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_document WHERE Id=@DocumentId) AND ";
    internal static readonly SqlStatement DocumentHost = new("ai.knowledge_faq_source.document_host", DocumentInsert + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement DocumentTenant = new("ai.knowledge_faq_source.document_tenant", DocumentInsert + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string DocumentUpdate = "UPDATE fn_ai_knowledge_document SET Title=@Title,UpdatedAtUtc=@Now,Version=@ExpectedHeadVersion WHERE Id=@DocumentId AND KnowledgeBaseId=@KnowledgeBaseId AND IsDeleted=0 AND Version<=@ExpectedHeadVersion AND EXISTS (SELECT 1 FROM fn_ai_knowledge_faq AS f INNER JOIN fn_ai_knowledge_base AS k ON k.Id=f.KnowledgeBaseId WHERE f.Id=@FaqId AND f.ReservedDocumentId=@DocumentId AND f.HeadRevisionId=@RevisionId AND f.HeadVersion=@ExpectedHeadVersion AND k.OwnerUserId=@OwnerUserId AND k.IsEnabled=1 AND ";
    internal static readonly SqlStatement UpdateDocumentHost = new("ai.knowledge_faq_source.update_document_host", DocumentUpdate + Host + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement UpdateDocumentTenant = new("ai.knowledge_faq_source.update_document_tenant", DocumentUpdate + Tenant + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string VersionInsert = "INSERT INTO fn_ai_knowledge_version (Id,DocumentId,FileId,FaqRevisionId,VersionNumber,OriginalFileName,ContentType,ParsingPolicyKey,ContentHash,SizeBytes,UploadedByUserId,CreatedAtUtc) SELECT input.Id,f.ReservedDocumentId,NULL,input.RevisionId,@ExpectedHeadVersion,'faq-revision','text/plain','faq-revision-text-v1',input.BodyHash,input.SizeBytes,input.ActorUserId,input.CreatedAtUtc" + Root;
    internal static readonly SqlStatement VersionHost = new("ai.knowledge_faq_source.version_host", VersionInsert + Host + " AND input.Id=@VersionId AND input.RevisionId=f.HeadRevisionId AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_version WHERE Id=@VersionId)", SqlDataScope.HostOnly);
    internal static readonly SqlStatement VersionTenant = new("ai.knowledge_faq_source.version_tenant", VersionInsert + Tenant + " AND input.Id=@VersionId AND input.RevisionId=f.HeadRevisionId AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_version WHERE Id=@VersionId)", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
}
